+      font-weight: 700;
+      letter-spacing: 0.02em;
+    }
+
+    h1 {
+      margin: 0 0 12px;
+      font-size: clamp(2rem, 4vw, 2.8rem);
+      line-height: 1.05;
+    }
+
+    .intro {
+      margin: 0 0 28px;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.6;
+    }
+
+    form {
+      display: grid;
+      gap: 24px;
+    }
+
+    .form-field {
+      padding: 24px;
+      border-radius: 20px;
+      border: 1px solid rgba(79, 70, 229, 0.16);
+      background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(244, 247, 255, 0.95));
+    }
+
+    fieldset {
+      margin: 0;
+      padding: 0;
+      border: 0;
+    }
+
+    legend {
+      margin: 0 0 10px;
+      font-size: 1.15rem;
+      font-weight: 700;
+    }
+
+    .field-help {
+      margin: 0 0 18px;
+      color: var(--muted);
+      font-size: 0.96rem;
+      line-height: 1.5;
+    }
+
+    .radio-group {
+      display: grid;
+      gap: 12px;
+    }
+
+    .radio-option {
+      display: flex;
+      align-items: center;
+      gap: 14px;
+      padding: 16px 18px;
+      border: 1px solid rgba(148, 163, 184, 0.35);
+      border-radius: 16px;
+      background: #ffffff;
+      cursor: pointer;
+      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
+    }
+
+    .radio-option:hover {
+      border-color: rgba(79, 70, 229, 0.45);
+      box-shadow: 0 10px 24px rgba(79, 70, 229, 0.08);
+      transform: translateY(-1px);
+    }
+
+    .radio-option:focus-within {
+      border-color: var(--accent);
+      box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.18);
+    }
+
+    input[type="radio"] {
+      inline-size: 20px;
+      block-size: 20px;
+      margin: 0;
+      accent-color: var(--accent);
+      flex: 0 0 auto;
+    }
+
+    .option-title {
+      font-weight: 600;
+    }
+
+    .actions {
+      display: flex;
+      justify-content: flex-start;
+    }
+
+    .submit-button {
+      border: 0;
+      border-radius: 999px;
+      padding: 14px 22px;
+      font: inherit;
+      font-weight: 700;
+      color: #ffffff;
+      background: linear-gradient(135deg, var(--accent), #7c3aed);
+      cursor: pointer;
+      box-shadow: 0 14px 28px rgba(79, 70, 229, 0.28);
+      transition: transform 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
+    }
+
+    .submit-button:hover {
+      transform: translateY(-1px);
+      box-shadow: 0 18px 34px rgba(79, 70, 229, 0.32);
+    }
+
+    .submit-button:focus-visible {
+      outline: 3px solid rgba(79, 70, 229, 0.28);
+      outline-offset: 3px;
+    }
+
+    .submit-button:active {
+      transform: translateY(0);
+    }
+
+    @media (max-width: 640px) {
+      .card {
+        padding: 24px;
+      }
+
+      .form-field {
+        padding: 20px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <div id="app"></div>
+  <script>
+    const options = [
+      { id: "notification-email", value: "Email", label: "Email" },
+      { id: "notification-sms", value: "SMS", label: "SMS" },
+      { id: "notification-push", value: "Push Notifications", label: "Push Notifications" }
+    ];
+
+    function RadioOption(option) {
+      return `
+        <label class="radio-option" for="${option.id}">
+          <input id="${option.id}" type="radio" name="notificationPreference" value="${option.value}" required />
+          <span class="option-title">${option.label}</span>
+        </label>
+      `;
+    }
+
+    function NotificationQuestion() {
+      return `
+        <div class="form-field">
+          <fieldset>
+            <legend>How do you prefer to receive notifications?</legend>
+            <p class="field-help">Choose one option so we know the best way to reach you.</p>
+            <div class="radio-group" role="radiogroup" aria-label="Notification preference">
+              ${options.map(RadioOption).join("")}
+            </div>
+          </fieldset>
+        </div>
+      `;
+    }
+
+    function FormSection() {
+      return `
+        <form>
+          ${NotificationQuestion()}
+          <div class="actions">
+            <button class="submit-button" type="submit">Submit</button>
+          </div>
+        </form>
+      `;
+    }
+
+    function App() {
+      return `
+        <main class="page-shell">
+          <section class="card" aria-labelledby="page-title">
+            <p class="eyebrow">Preferences</p>
+            <h1 id="page-title">Choose your notification channel</h1>
+            <p class="intro">Set a single preferred method for product updates and account alerts with a simple, focused form.</p>
+            ${FormSection()}
+          </section>
+        </main>
+      `;
+    }
+
+    document.getElementById("app").innerHTML = App();
+  </script>
+</body>
+</html>
*** End Patch
