      width: min(100%, 720px);
      background: var(--panel);
      backdrop-filter: blur(16px);
      border: 1px solid var(--panel-border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 32px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin: 0 0 16px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(79, 70, 229, 0.1);
      color: var(--accent-strong);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.02em;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 4vw, 2.8rem);
      line-height: 1.05;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 24px;
    }

    .form-field {
      padding: 24px;
      border-radius: 20px;
      border: 1px solid rgba(79, 70, 229, 0.16);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(244, 247, 255, 0.95));
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin: 0 0 10px;
      font-size: 1.15rem;
      font-weight: 700;
    }

    .field-help {
      margin: 0 0 18px;
      color: var(--muted);
      font-size: 0.96rem;
      line-height: 1.5;
    }

    .radio-group {
      display: grid;
      gap: 12px;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 16px 18px;
      border: 1px solid rgba(148, 163, 184, 0.35);
      border-radius: 16px;
      background: #ffffff;
      cursor: pointer;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    .radio-option:hover {
      border-color: rgba(79, 70, 229, 0.45);
      box-shadow: 0 10px 24px rgba(79, 70, 229, 0.08);
      transform: translateY(-1px);
    }

    .radio-option:focus-within {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.18);
    }

    input[type="radio"] {
      inline-size: 20px;
      block-size: 20px;
      margin: 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .option-title {
      font-weight: 600;
    }

    .actions {
      display: flex;
      justify-content: flex-start;
    }

    .submit-button {
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      font: inherit;
      font-weight: 700;
      color: #ffffff;
      background: linear-gradient(135deg, var(--accent), #7c3aed);
      cursor: pointer;
      box-shadow: 0 14px 28px rgba(79, 70, 229, 0.28);
      transition: transform 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
    }

    .submit-button:hover {
      transform: translateY(-1px);
      box-shadow: 0 18px 34px rgba(79, 70, 229, 0.32);
    }

    .submit-button:focus-visible {
      outline: 3px solid rgba(79, 70, 229, 0.28);
      outline-offset: 3px;
    }

    .submit-button:active {
      transform: translateY(0);
    }

    @media (max-width: 640px) {
      .card {
        padding: 24px;
      }

      .form-field {
        padding: 20px;
      }
    }
  </style>
</head>
